A conversão de cada **`ProdutoDistribuicao`** (entidade de domínio) para o proto **`ProdutoVitrine`** é realizada por uma *converter* personalizada do AutoMapper.  O trecho abaixo mostra exatamente como cada campo do JSON que você enviou é construído:

```csharp
public class ProdutoDistribuicaoToProdutoVitrineConverter :
    ITypeConverter<Domain.Entities.ProdutoDistribuicao, ProdutoVitrine>
{
    public ProdutoVitrine Convert(
        Domain.Entities.ProdutoDistribuicao source,
        ProdutoVitrine destination,
        ResolutionContext context)
    {
        // 1 – Campos gerais do produto
        var response = new ProdutoVitrine
        {
            Id              = source.Produto.Id.ToString(),
            Nome            = source.Produto.Nome,
            ImagemParceiro  = source.ImagemParceiroUrl ?? string.Empty,
            Descricao       = source.Produto.Descricao,
            Rodape          = source.Produto.Rodape ?? string.Empty,
            Alerta          = source.Produto.Alerta ?? string.Empty
        };

        // 2 – Informações do ramos/Grupo – se houver componente principal
        if (source.Produto.TemComponentePrincipal)
        {
            var apolice = source.Produto.ComponentePrincipal.Apolices.FirstOrDefault();
            var ramo    = apolice.Ramo;

            response.Ramo = new Protos.Ramo
            {
                Id          = ramo.Id.ToString(),
                Codigo      = ramo.Codigo,
                Descricao   = ramo.Descricao
            };

            response.Grupo = new Protos.Grupo
            {
                Id          = ramo.Grupo.Id.ToString(),
                Codigo      = ramo.Grupo.Codigo,
                Descricao   = ramo.Grupo.Descricao
            };

            // Lojista e série
            response.LojistaId = source.Produto.ComponentePrincipal.Apolices
                    .FirstOrDefault()
                    .ApolicesPessoas
                      .FirstOrDefault(ap => ap.Vinculo == TipoVinculoApolice.Estipulante
                                || ap.Vinculo == TipoVinculoApolice.Representante)
                      .LojistaId.ToString();

            response.Serie      = source.Produto.ComponentePrincipal.Serie ?? string.Empty;
            response.Modalidade = apolice.Modalidade ?? string.Empty;
        }

        // 3 – Tipo Pessoa (principal ou de plano)
        response.TipoPessoa = ObterTipoPessoaContratacao(source);

        // 4 – Métodos de pagamento
        if (source.MetodosPagamento.Any())
        {
            response.MetodosPagamento.AddRange(
                source.MetodosPagamento
                    .GroupBy(mp => mp.MetodoPagamento)
                    .Select(grouped =>
                    {
                        var metodo = new MetodoPagamentoComFormaDetalhe
                        {
                            Id          = grouped.Key.Id.ToString(),
                            Codigo      = grouped.Key.Codigo,
                            Descricao   = grouped.Key.Descricao,
                            Icone       = grouped.Key.Icone ?? string.Empty
                        };

                        if (grouped.Any(g => g.FormaPagamento != null))
                        {
                            metodo.FormasPagamento.AddRange(
                                grouped.Select(g => new FormaPagamentoDetalhe
                                {
                                    Id          = g.FormaPagamento.Id.ToString(),
                                    Nome        = g.FormaPagamento.Nome,
                                    Icone       = g.FormaPagamento.Icone ?? string.Empty,
                                    Recorrencia = g.FormaPagamento.Recorrencia
                                }));
                        }

                        return metodo;
                    })
            );
        }

        // 5 – Configuração da vitrine
        var componenteConfiguracao = source.Produto.ComponentePrincipal?.ComponenteConfiguracao
                                    ?? ComponenteConfiguracaoConstant.Padrao;

        response.Configuracao = context.Mapper.Map<ConfiguracaoProdutoVitrine>(componenteConfiguracao);
        response.Configuracao.TiposAutorizacao?.AddRange(
            source.Produto.ObterTiposAutorizacao()
        );

        // 6 – Menor valor do plano e periodicidade
        if (source.Produto.ProdutoPlanos.Any())
        {
            var menor = source.Produto.ProdutoPlanos.MinBy(pl => pl.Valor);
            if (menor != null)
            {
                response.MenorValorPlano      = decimal.ToDouble(menor.Valor);
                response.PeriodicidadePagamento = menor.ObterPeriodicidadePagamento();
            }
        }

        return response;
    }

    private string ObterTipoPessoaContratacao(Domain.Entities.ProdutoDistribuicao pd)
    {
        if (pd.Produto.TemComponentePrincipal)
            return pd.Produto.ComponentePrincipal.TipoPessoa;

        var componente = pd.Produto.ProdutoPlanos
                .SelectMany(pp => pp.ProdutoPlanoMontagens
                                 .Select(m => m.ComponentePlano.Componente))
                .FirstOrDefault();

        return componente?.TipoPessoa ?? string.Empty;
    }
}
```

**Resumo do mapeamento:**

| Campo no JSON | Origem na entidade de domínio | Trecho no código |
|---------------|------------------------------|------------------|
| `id` | `source.Produto.Id`   | `Id = source.Produto.Id.ToString()` |
| `nome` | `source.Produto.Nome` | `Nome = source.Produto.Nome` |
| `descricao` | `source.Produto.Descricao` | `Descricao = source.Produto.Descricao` |
| `imagem` | `source.ImagemParceiroUrl` | `ImagemParceiro = source.ImagemParceiroUrl ?? string.Empty` |
| `menorValorPlano` | `Menor valor dos planos` | `MenorValorPlano = decimal.ToDouble(menor.Valor)` |
| `periodicidadePagamento` | Lista de planos | `PeriodicidadePagamento = menor.ObterPeriodicidadePagamento()` |
| `grupo`, `ramo`, `modalidade`, `serie`, `lojaId`, etc. | Se houver componente principal | Bloco dentro da condição `source.Produto.TemComponentePrincipal` |
| `configuracao` | `componenteConfiguracao` | `response.Configuracao = context.Mapper.Map<ConfiguracaoProdutoVitrine>(componenteConfiguracao)` |
| `tiposAutorizacao`, `metodos_payment` | Dentro do produto ou planos | Seção “Estado de pagamento” e “Configuração da vitrine” |

Assim, o handler (`ListarParaVitrine`) obtém a lista de domínios e delega a conversão de cada entidade para o proto ao AutoMapper, que usa este `ProdutoDistribuicaoToProdutoVitrineConverter`.  Cada linha do JSON enviado pelo cliente é exatamente construída conforme os trechos acima.

