public List<UnidadeVenda> ListarUnidadesVenda(List<Guid> origensId, int pagina, int porPagina, string[] ordenacoes, string[] filtros)
{
    var query = _context.UnidadesVenda
        .Where(uv => origensId.Contains(uv.OrigemId)) // Certifique-se de que OrigemId seja uma propriedade válida
        .OrderBy(uv => uv.OrigemId) // Certifique-se de que OrigemId seja uma propriedade válida
        .Skip(pagina * porPagina)
        .Take(porPagina);

    return query.ToList();
}
```

### 2. **Tratar Referências Nulas no Código**

**Erro:**
- **Span ID:** `460044802686055744`
